#!/usr/bin/env python3
"""Extract the heart-placement layer of pinned Basement normal-room templates.

Room selection, other actors/grid, eligibility and source seed mapping are not
reproduced by extracting this layer. No game install writes or sprite imports.
"""
import argparse,hashlib,json,struct
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
SOURCE=ROOT/'reference/isaac-repentance-1.7.9b/extracted/repentance/resources-dlc3/rooms/01.basement.stb'
OUT=ROOT/'docs/reports/isaac-first-floor-parity/d09a-room-hearts'
SHA='524406fcb10c6275995292c0bd024cfc43d3d30c32b233e55d4d514573d963b0'
def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args()
    data=SOURCE.read_bytes();assert hashlib.sha256(data).hexdigest()==SHA
    magic,count=struct.unpack_from('<4sI',data);assert magic==b'STB1';offset=8;pool=[];rock_room=[];chest_room=[];coin_room=[];key_room=[];bomb_room=[];combat_rooms={v:[] for v in (4,108,109,547,548,550)}
    def take(fmt):
        nonlocal offset
        result=struct.unpack_from(fmt,data,offset);offset+=struct.calcsize(fmt);return result
    for index in range(count):
        kind,variant,subtype,difficulty,n=take('<IIIBH');offset+=n
        weight,width,height,shape,doors,stacks=take('<fBBBBH')
        door_mask=0
        for _ in range(doors):
            x,y,exists=take('<hh?')
            if shape==1 and exists:
                # Ordinary 13x7 source door slots: left/up/right/down.
                door_mask|=1<<{(-1,3):0,(6,-1):1,(13,3):2,(6,7):3}[(x,y)]
        slots=[]
        for ordinal in range(stacks):
            x,y,entries=take('<hhB')
            choices=[dict(zip(('type','variant','subtype','weight'),take('<HHHf'))) for _ in range(entries)]
            if (kind,variant,subtype)==(1,91,0):rock_room.append(dict(x=x,y=y,choices=choices))
            if (kind,variant,subtype)==(1,31,0):chest_room.append(dict(ordinal=ordinal,x=x,y=y,choices=choices))
            if (kind,variant,subtype)==(1,214,0):key_room.append(dict(ordinal=ordinal,x=x,y=y,choices=choices))
            if (kind,variant,subtype)==(1,32,0):bomb_room.append(dict(ordinal=ordinal,x=x,y=y,choices=choices))
            if (kind,variant,subtype)==(1,30,0):coin_room.append(dict(ordinal=ordinal,x=x,y=y,choices=choices))
            if kind==1 and subtype==0 and variant in combat_rooms:combat_rooms[variant].append(dict(x=x,y=y,choices=choices))
            # Preserve competing non-heart choices in mixed stacks; never
            # renormalize a bomb/sack/etc. into an extra heart.
            if any(c['type']==5 and c['variant']==10 for c in choices):slots.append(dict(ordinal=ordinal,x=x,y=y,choices=choices))
        if kind==1 and weight>0 and 1<=difficulty<=5 and shape==1 and (width,height)==(13,7):
            pool.append(dict(index=index,type=kind,variant=variant,subtype=subtype,difficulty=difficulty,shape=shape,doors=door_mask,weight=weight,spawnCount=stacks,slots=slots))
    assert offset==len(data)
    assert len(pool)==433
    entries=[];slots=[];layouts=[]
    for r in pool:
        layouts.append((r['type'],r['variant'],r['subtype'],r['difficulty'],r['shape'],r['doors'],r['weight'],len(slots),len(r['slots']),r['spawnCount']))
        for slot in r['slots']:
            slots.append((slot['x'],slot['y'],len(entries),len(slot['choices']),slot['ordinal']))
            entries.extend((c['type'],c['variant'],c['subtype'],c['weight']) for c in slot['choices'])
    header='''// Generated by scripts/isaac-reference/extract-room-heart-layouts.py; do not hand edit.
#pragma once
#include <array>
namespace dw {
struct SourceRoomHeartLayout {int type,variant,subtype,difficulty,shape,doors;float weight;int firstSlot,slotCount,spawnCount;};
struct SourceRoomHeartSlot {int x,y,firstChoice,choiceCount,ordinal;};
struct SourceRoomHeartChoice {int type,variant,subtype;float weight;};
'''
    for typ,name,rows in [('SourceRoomHeartLayout','BasementHeartLayouts',layouts),('SourceRoomHeartSlot','BasementHeartSlots',slots),('SourceRoomHeartChoice','BasementHeartChoices',entries)]:
        header+=f'inline constexpr std::array<{typ},{len(rows)}> {name}{{{{\n'
        for row in rows:header+='    {'+','.join(str(x) if isinstance(x,int) else format(x,'.9g')+'f' if '.' in format(x,'.9g') else format(x,'.9g')+'.f' for x in row)+'},\n'
        header+='}};\n'
    header+='} // namespace dw\n'
    manifest=dict(source=str(SOURCE.relative_to(ROOT)),sha256=SHA,target='Installed Repentance 1.7.9b',filter='type1, positive weight, difficulty1-5, shape1, 13x7; includes templates with zero heart slots',template_count=len(pool),heart_slot_count=len(slots),choice_count=len(entries),scope='Heart layer only. The main-game adapter uses the verified native numeric/weighted selector and spawn-slot sequence with DW door/difficulty/seed inputs. Native caller/floor selection, full actors/grid, unlock filters and descriptor RNG are not certified.',templates=pool)
    rocks=[(s['x'],s['y']) for s in rock_room if s['choices']==[dict(type=1000,variant=0,subtype=0,weight=1.0)]]
    assert len(rock_room)==21 and len(rocks)==19
    assert [s for s in rock_room if (s['x'],s['y']) not in rocks]==[dict(x=x,y=3,choices=[dict(type=5,variant=10,subtype=0,weight=1.0)]) for x in (5,7)]
    rock_header='// Generated by scripts/isaac-reference/extract-room-heart-layouts.py.\n#pragma once\n#include <array>\nnamespace dw {\ninline constexpr std::array<std::array<int,2>,19> Basement91Rocks{{\n'
    rock_header+=''.join(f'    {{{x},{y}}},\n' for x,y in rocks)+'}};\n} // namespace dw\n'
    rock_manifest=dict(source=str(SOURCE.relative_to(ROOT)),sha256=SHA,template='1.91.0',slots=rock_room,rock_count=19,heart_slots=2,enemies=0,scope='Complete source content record. Native runtime grid substitution, drops and physical collision remain separate verification.')
    combat_header='// Generated by scripts/isaac-reference/extract-room-heart-layouts.py.\n#pragma once\n#include <array>\nnamespace dw {\n'
    combat_outputs=[]
    for variant,combat_room in combat_rooms.items():
        combat_rocks=[(s['x'],s['y']) for s in combat_room if s['choices']==[dict(type=1000,variant=0,subtype=0,weight=1.0)]]
        gapers=[(s['x'],s['y']) for s in combat_room if s['choices']==[dict(type=10,variant=1,subtype=0,weight=1.0)]]
        if variant==4:
            assert len(combat_room)==19 and len(combat_rocks)==17 and gapers==[(10,1),(2,5)]
        elif variant==108:
            assert len(combat_room)==13 and len(combat_rocks)==9 and gapers==[(6,2),(5,3),(7,3),(6,4)]
        else:
            expected={109:(5,8),547:(2,39),548:(1,52),550:(2,33)}[variant]
            assert (len(gapers),len(combat_rocks))==expected and len(combat_room)==sum(expected)
        for name,rows in [(f'Basement{variant}Rocks',combat_rocks),(f'Basement{variant}Gapers',gapers)]:
            combat_header+=f'inline constexpr std::array<std::array<int,2>,{len(rows)}> {name}{{{{\n'
            combat_header+=''.join(f'    {{{x},{y}}},\n' for x,y in rows)+'}};\n'
        metadata=next(r for r in pool if (r['type'],r['variant'],r['subtype'])==(1,variant,0))
        combat_manifest=dict(source=str(SOURCE.relative_to(ROOT)),sha256=SHA,template=f'1.{variant}.0',metadata=metadata,slots=combat_room,rock_count=len(combat_rocks),gapers=len(gapers),pickups=0,scope='Complete source content record. Canyon size, shape and connections are retained; native runtime grid substitution, actor AI, drops and physics are separate verification.')
        destination='native-combat-rock-room' if variant==4 else 'native-four-gaper-room' if variant==108 else f'native-room-coverage/room-{variant}'
        combat_outputs.append((OUT.parent/destination/'source-room.json',json.dumps(combat_manifest,indent=2)+'\n'))
    combat_header+='} // namespace dw\n'
    chest_rocks=[(s['x'],s['y']) for s in chest_room if s['choices']==[dict(type=1000,variant=0,subtype=0,weight=1.0)]]
    chest_slots=[s for s in chest_room if (s['x'],s['y']) not in chest_rocks]
    assert len(chest_room)==13 and len(chest_rocks)==12
    assert chest_slots==[dict(ordinal=6,x=6,y=3,choices=[dict(type=5,variant=50,subtype=0,weight=1.0)])]
    chest_header='// Generated by scripts/isaac-reference/extract-room-heart-layouts.py.\n#pragma once\n#include <array>\nnamespace dw {\ninline constexpr int SourceChestRockRoom=31;\ninline constexpr int Basement31ChestOrdinal=6;\ninline constexpr std::array<int,2> Basement31ChestCell{6,3};\ninline constexpr std::array<std::array<int,2>,12> Basement31Rocks{{\n'
    chest_header+=''.join(f'    {{{x},{y}}},\n' for x,y in chest_rocks)+'}};\n} // namespace dw\n'
    chest_manifest=dict(source=str(SOURCE.relative_to(ROOT)),sha256=SHA,template='1.31.0',metadata=next(r for r in pool if (r['type'],r['variant'],r['subtype'])==(1,31,0)),slots=chest_room,rock_count=12,chests=1,enemies=0,scope='Complete source content record. Ordinary chest contents/physics use the existing explicit DeathWard adaptation; source size/shape/connections remain excluded.')
    chest_outputs=[(ROOT/'src/world/SourceChestRockRoomData.hpp',chest_header),(OUT.parent/'preplaced-chests/source-room.json',json.dumps(chest_manifest,indent=2)+'\n')]
    coin_rocks=[(s['x'],s['y']) for s in coin_room if s['choices']==[dict(type=1000,variant=0,subtype=0,weight=1.0)]]
    coin_slots=[s for s in coin_room if (s['x'],s['y']) not in coin_rocks]
    assert len(coin_room)==5 and coin_rocks==[(6,3)]
    assert coin_slots==[dict(ordinal=o,x=x,y=y,choices=[dict(type=5,variant=20,subtype=0,weight=1.0)]) for o,x,y in [(0,6,2),(1,5,3),(3,7,3),(4,6,4)]]
    coin_header='// Generated by scripts/isaac-reference/extract-room-heart-layouts.py.\n#pragma once\n#include <array>\nnamespace dw {\ninline constexpr int SourceCoinRockRoom=30;\nstruct SourceCoinSlot {int ordinal,x,y,subtype;};\ninline constexpr std::array<SourceCoinSlot,4> Basement30Coins{{\n'
    coin_header+=''.join(f"    {{{s['ordinal']},{s['x']},{s['y']},{s['choices'][0]['subtype']}}},\n" for s in coin_slots)+'}};\ninline constexpr std::array<std::array<int,2>,1> Basement30Rocks{{{6,3}}};\n} // namespace dw\n'
    coin_manifest=dict(source=str(SOURCE.relative_to(ROOT)),sha256=SHA,template='1.30.0',metadata=next(r for r in pool if (r['type'],r['variant'],r['subtype'])==(1,30,0)),slots=coin_room,rock_count=1,coins=4,enemies=0,scope='Complete source content record. Descriptor/slot seeds and ordinary coin resolver are reused; canyon scale/shape/connections, pickup physics and profile/factory remain explicit adaptation or verification limits.')
    coin_outputs=[(ROOT/'src/world/SourceCoinRockRoomData.hpp',coin_header),(OUT.parent/'preplaced-coins/source-room.json',json.dumps(coin_manifest,indent=2)+'\n')]
    key_rocks=[(s['x'],s['y']) for s in key_room if s['choices']==[dict(type=1000,variant=0,subtype=0,weight=1.0)]]
    key_slots=[s for s in key_room if (s['x'],s['y']) not in key_rocks]
    assert len(key_room)==20 and len(key_rocks)==18
    assert key_slots==[dict(ordinal=o,x=x,y=y,choices=[dict(type=5,variant=30,subtype=0,weight=1.0)]) for o,x,y in [(4,3,2),(15,9,4)]]
    key_header='// Generated by scripts/isaac-reference/extract-room-heart-layouts.py.\n#pragma once\n#include <array>\nnamespace dw {\ninline constexpr int SourceKeyRockRoom=214;\nstruct SourceKeySlot {int ordinal,x,y,subtype;};\ninline constexpr std::array<SourceKeySlot,2> Basement214Keys{{\n'
    key_header+=''.join(f"    {{{s['ordinal']},{s['x']},{s['y']},{s['choices'][0]['subtype']}}},\n" for s in key_slots)+'}};\ninline constexpr std::array<std::array<int,2>,18> Basement214Rocks{{\n'
    key_header+=''.join(f'    {{{x},{y}}},\n' for x,y in key_rocks)+'}};\n} // namespace dw\n'
    key_manifest=dict(source=str(SOURCE.relative_to(ROOT)),sha256=SHA,template='1.214.0',metadata=next(r for r in pool if (r['type'],r['variant'],r['subtype'])==(1,214,0)),slots=key_room,rock_count=18,keys=2,enemies=0,scope='Complete source content record; original descriptor/slot seeds. Canyon geometry, dynamite, pickup contact/physics and full source profile remain adaptations or verification limits.')
    key_outputs=[(ROOT/'src/world/SourceKeyRockRoomData.hpp',key_header),(OUT.parent/'d09c-keys/source-room.json',json.dumps(key_manifest,indent=2)+'\n')]
    bomb_rocks=[(s['x'],s['y']) for s in bomb_room if s['choices']==[dict(type=1000,variant=0,subtype=0,weight=1.0)]]
    bomb_slots=[s for s in bomb_room if (s['x'],s['y']) not in bomb_rocks]
    assert len(bomb_room)==37 and len(bomb_rocks)==34
    assert bomb_slots==[dict(ordinal=o,x=x,y=y,choices=[dict(type=5,variant=40,subtype=0,weight=1.0)]) for o,x,y in [(17,5,3),(18,6,3),(19,7,3)]]
    bomb_header='// Generated by scripts/isaac-reference/extract-room-heart-layouts.py.\n#pragma once\n#include <array>\nnamespace dw {\ninline constexpr int SourceBombRockRoom=32;\nstruct SourceBombSlot {int ordinal,x,y,subtype;};\ninline constexpr std::array<SourceBombSlot,3> Basement32Bombs{{\n'
    bomb_header+=''.join(f"    {{{s['ordinal']},{s['x']},{s['y']},{s['choices'][0]['subtype']}}},\n" for s in bomb_slots)+'}};\ninline constexpr std::array<std::array<int,2>,34> Basement32Rocks{{\n'
    bomb_header+=''.join(f'    {{{x},{y}}},\n' for x,y in bomb_rocks)+'}};\n} // namespace dw\n'
    bomb_manifest=dict(source=str(SOURCE.relative_to(ROOT)),sha256=SHA,template='1.32.0',metadata=next(r for r in pool if (r['type'],r['variant'],r['subtype'])==(1,32,0)),slots=bomb_room,rock_count=34,bombs=3,enemies=0,scope='Complete source content record; original descriptor/slot seeds. Canyon geometry, dynamite, pickup contact/physics and full source profile remain adaptations or verification limits.')
    bomb_outputs=[(ROOT/'src/world/SourceBombRockRoomData.hpp',bomb_header),(OUT.parent/'d09d-bombs/source-room.json',json.dumps(bomb_manifest,indent=2)+'\n')]
    for path,content in [(OUT/'source-layouts.json',json.dumps(manifest,indent=2)+'\n'),(ROOT/'src/world/SourceRoomHeartsData.hpp',header),(ROOT/'src/world/SourceHeartRockRoomData.hpp',rock_header),(OUT.parent/'native-heart-rock-room/source-room.json',json.dumps(rock_manifest,indent=2)+'\n'),(ROOT/'src/world/SourceCombatRockRoomData.hpp',combat_header),*combat_outputs,*chest_outputs,*coin_outputs,*key_outputs,*bomb_outputs]:
        if args.check:assert path.read_text()==content,path
        else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content)
    print(f'PASS {len(pool)} templates including empty heart layers, {len(slots)} heart stacks and {len(entries)} weighted choices')
if __name__=='__main__':main()
